/* ============================================================
 * C0/9AA1, C0/9AC8, C0/9AB2 (fetch) + C0/9AD3 (shape-decode prologue)
 * DP=$1D00 (D set at C0/881E and at the 9DDE re-entry's 9DE1 TCD), so $XX = $7E:1DXX.
 * Re-decode VERIFIED byte-exact against the ROM. Trace is SILENT on this path.
 *
 * INPUTS:
 *   A on entry = 16-bit "cell source" position word.
 *     Callers 8A9E / 9C87: A = ($1D69<<8) | $1D67  (LDA $68 16-bit; SEP; LDA $67 8-bit)
 *     Caller 9DE5:         A = ($0103<<8) | $0102  (LDA $0102 16-bit; SEP)
 *   $1D1E/$1D1F (16-bit) = CELL MASK; (A & mask) = linear byte index into the
 *     0x40-stride property planes (upstream-built; opaque to this cluster).
 * OUTPUTS:
 *   carry: SET = off-map / treat as SOLID;  CLEAR = in-bounds (3 bytes loaded).
 *   $1D58=byte0 (raw; shape decoded later at 9AE5 as (byte0&0xFC)>>2, 6-bit;
 *               bit0/bit1 = actor-block flags)
 *   $1D5A=byte1 (byte1&0x10 = DOOR; conveyor source consumed at apply 9C5C)
 *   $1D5C=byte2 (byte2&3 = z-plane; &4 IGNORE_Z; &8 INVERTED; &0x20 Z_NEUTRAL;
 *               &0x40 SPRITE_FRONT_BOTTOM)
 *   X (16-bit during fetch, restored 8-bit at 9AC4) = computed cell index, persists.
 * PLANES (absolute long WRAM; X is the index):
 *   $7E70C0 off-map SENTINEL (bit7 SET => VALID cell; bit7 CLEAR => off-map);
 *   $7E30C0 byte0; $7E7000 byte1; $7E7040 byte2.
 * ============================================================ */

/* ---- C0/9AA1 : fetch WITH off-map sentinel early-out ---- */
bool prop_fetch_checked(uint16_t pos_word)
{
    /* 9AA1 REP #$10 ; 9AA3 REP #$20  -> X & A 16-bit */
    uint16_t X = pos_word & DP16(0x1E);        /* 9AA5 AND $1E ; 9AA7 SEP #$20 ; 9AA9 TAX */
    uint8_t sentinel = WRAM8(0x7E70C0 + X);    /* 9AAA LDA $7E70C0,X (A now 8-bit) */
    if (sentinel & 0x80)                        /* 9AAE BMI $9AB2 : taken iff bit7 SET (VALID) */
        return prop_fetch_tail(X);             /*   -> load bytes, carry CLEAR */
    /* 9AB0 SEC ; 9AB1 RTS  -- bit7 CLEAR => off-map */
    return true;                               /* CARRY SET = SOLID */
}

/* ---- C0/9AB2 : common tail (load 3 prop bytes, carry clear) ---- */
bool prop_fetch_tail(uint16_t X)
{
    DP8(0x58) = WRAM8(0x7E30C0 + X);           /* 9AB2 LDA $7E30C0,X ; 9AB6 STA $58 */
    DP8(0x5A) = WRAM8(0x7E7000 + X);           /* 9AB8 LDA $7E7000,X ; 9ABC STA $5A */
    DP8(0x5C) = WRAM8(0x7E7040 + X);           /* 9ABE LDA $7E7040,X ; 9AC2 STA $5C */
    /* 9AC4 SEP #$10 (X->8-bit) ; 9AC6 CLC ; 9AC7 RTS */
    return false;                              /* CARRY CLEAR = in-bounds */
}

/* ---- C0/9AC8 : fetch WITHOUT sentinel check (always loads) ---- */
bool prop_fetch_unchecked(uint16_t pos_word)
{
    /* 9AC8 REP #$10 ; 9ACA REP #$20 */
    uint16_t X = pos_word & DP16(0x1E);        /* 9ACC AND $1E ; 9ACE SEP #$20 ; 9AD0 TAX */
    return prop_fetch_tail(X);                 /* 9AD1 BRA $9AB2 (always carry CLEAR) */
}

/* ---- C0/9AD3 : shape-decode prologue (NOT a fetch; flows into 9AE3 decoder) ---- */
void collision_result_init_and_shape_head(void)
{
    DP8(0x5E) = 0;                             /* 9AD3 STZ $5E  one-way scratch */
    DP8(0x60) = 0;                             /* 9AD5 STZ $60  shape-index scratch */
    DP8(0x6A) = 0;                             /* 9AD7 STZ $6A  z-plane out */
    DP8(0x6C) = 0;                             /* 9AD9 STZ $6C  IGNORE_Z out */
    DP8(0x6E) = 0;                             /* 9ADB STZ $6E  sprite-prio out */
    DP8(0x56) = DP8(0x68) >> 2;                /* 9ADD LDA $68 ; 9ADF LSR ; 9AE0 LSR ; 9AE1 STA $56 */
    /* 9AE3 LDA $58 -> shape decode: shape = (byte0 & 0xFC) >> 2  (6-bit) ... */
}
